/* @autogenerated */
package net.civeira.phylax.features.oauth.client.domain;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class ClientDetailsUnitTest {

  private ClientDetails publicClient() {
    return ClientDetails.builder().clientId("client-public")
        .allowedScopes(List.of("openid", "profile", "email"))
        .allowedGrants(List.of("authorization_code", "refresh_token")).protectedWithSecret(false)
        .requirePkce(true).build();
  }

  @Test
  @DisplayName("allowedScope returns true for permitted scope and false otherwise")
  void test_allowed_scope() {
    ClientDetails client = publicClient();
    Assertions.assertTrue(client.allowedScope("openid"));
    Assertions.assertTrue(client.allowedScope("profile"));
    Assertions.assertFalse(client.allowedScope("admin"));
    Assertions.assertFalse(client.allowedScope(""));
  }

  @Test
  @DisplayName("allowedGrant returns true for permitted grant and false otherwise")
  void test_allowed_grant() {
    ClientDetails client = publicClient();
    Assertions.assertTrue(client.allowedGrant("authorization_code"));
    Assertions.assertTrue(client.allowedGrant("refresh_token"));
    Assertions.assertFalse(client.allowedGrant("client_credentials"));
    Assertions.assertFalse(client.allowedGrant("device_code"));
  }

  @Test
  @DisplayName("findBackchannelLogoutUri returns empty when not set")
  void test_backchannel_logout_uri_absent() {
    ClientDetails client = publicClient();
    Assertions.assertFalse(client.findBackchannelLogoutUri().isPresent());
  }

  @Test
  @DisplayName("findBackchannelLogoutUri returns empty for blank URI")
  void test_backchannel_logout_uri_blank() {
    ClientDetails client = ClientDetails.builder().clientId("c").allowedScopes(List.of())
        .allowedGrants(List.of()).backchannelLogoutUri("   ").build();
    Assertions.assertFalse(client.findBackchannelLogoutUri().isPresent());
  }

  @Test
  @DisplayName("findBackchannelLogoutUri returns URI when present")
  void test_backchannel_logout_uri_present() {
    ClientDetails client = ClientDetails.builder().clientId("c").allowedScopes(List.of())
        .allowedGrants(List.of()).backchannelLogoutUri("https://app.example.com/logout").build();
    Assertions.assertTrue(client.findBackchannelLogoutUri().isPresent());
    Assertions.assertEquals("https://app.example.com/logout",
        client.findBackchannelLogoutUri().get());
  }

  @Test
  @DisplayName("postLogoutRedirectUris defaults to empty list")
  void test_default_post_logout_uris() {
    ClientDetails client = publicClient();
    Assertions.assertNotNull(client.getPostLogoutRedirectUris());
    Assertions.assertTrue(client.getPostLogoutRedirectUris().isEmpty());
  }

  @Test
  @DisplayName("Response types are compared as sets and code needs the authorization_code grant")
  void test_allows_response_type() {
    ClientDetails hybrid = ClientDetails.builder().clientId("c").allowedScopes(List.of())
        .allowedGrants(List.of("authorization_code"))
        .allowedResponseTypes(List.of("code", "code id_token")).build();
    Assertions.assertTrue(hybrid.allowsResponseType("code"));
    Assertions.assertTrue(hybrid.allowsResponseType("id_token code"));
    Assertions.assertFalse(hybrid.allowsResponseType("token"));
    Assertions.assertFalse(hybrid.allowsResponseType(" "));
    ClientDetails m2m = ClientDetails.builder().clientId("c").allowedScopes(List.of())
        .allowedGrants(List.of("client_credentials")).build();
    Assertions.assertFalse(m2m.allowsResponseType("code"));
  }

  @Test
  @DisplayName("The mfa grant follows the password grant")
  void test_mfa_follows_password() {
    ClientDetails withPassword = ClientDetails.builder().clientId("c").allowedScopes(List.of())
        .allowedGrants(List.of("password")).build();
    Assertions.assertTrue(withPassword.allowedGrant("mfa"));
    Assertions.assertFalse(publicClient().allowedGrant("mfa"));
  }

  @Test
  @DisplayName("M2M scopes: all of them by default, the requested subset otherwise")
  void test_m2m_scopes() {
    ClientDetails client = ClientDetails.builder().clientId("c").allowedScopes(List.of("*"))
        .allowedGrants(List.of("client_credentials"))
        .allowedScopesM2m(List.of("orders:read", "orders:write")).build();
    Assertions.assertEquals(List.of("orders:read", "orders:write"), client.m2mScopes(List.of()));
    Assertions.assertEquals(List.of("orders:read"),
        client.m2mScopes(List.of("orders:read", "admin")));
    Assertions.assertEquals(List.of(), client.m2mScopes(List.of("admin")));
    Assertions.assertEquals(List.of(), publicClient().m2mScopes(List.of()));
  }

  @Test
  @DisplayName("User scopes are compared exactly: myprofile does not grant profile")
  void test_grantable_scopes_exact() {
    ClientDetails client = ClientDetails.builder().clientId("c")
        .allowedScopes(List.of("openid", "myprofile")).allowedGrants(List.of()).build();
    Assertions.assertEquals(List.of("myprofile"),
        client.grantableScopes(List.of("profile", "myprofile")));
  }

  @Test
  @DisplayName("Scopes granted by the login are kept next to the requested ones (root tenant)")
  void test_grantable_scopes_keep_granted() {
    ClientDetails client = ClientDetails.builder().clientId("c")
        .allowedScopes(List.of("openid", "profile")).allowedGrants(List.of()).build();
    Assertions.assertEquals(List.of("openid", "profile", "platform:global_access"),
        client.grantableScopes(List.of("openid", "profile", "admin"),
            List.of("platform:global_access", "openid")));
    Assertions.assertEquals(List.of("openid"), client.grantableScopes(List.of("openid"), null));
    Assertions.assertEquals(List.of("platform:global_access"),
        client.grantableScopes(List.of(), List.of("platform:global_access")));
  }
}
